class RetryConfig {
    int maxAttempts;
    long delayMs;
    Set<Class<? extends Exception>> retryOn;
}

class FixedDelayRetry {

    static <T> T execute(RetryConfig cfg, Callable<T> action) throws Exception {
        int attempt = 0;
        while (true) {
            try {
                return action.call();
            } catch (Exception e) {
                attempt++;
                boolean retryable = cfg.retryOn.stream()
                    .anyMatch(c -> c.isInstance(e));
                if (!retryable || attempt >= cfg.maxAttempts) throw e;
                log.warn("Attempt {} failed, retrying in {}ms", attempt, cfg.delayMs, e);
                Thread.sleep(cfg.delayMs);
            }
        }
    }
}

