                System.out.println("Attempt " + attempt + " failed, retrying in " + cfg.delayMs + "ms: " + e.getMessage());
                Thread.sleep(cfg.delayMs);
            }
        }
    }
}

public class Main {
    static int callCount = 0;

    static String flakyCharge() throws Exception {
        callCount++;
        if (callCount < 3) throw new java.util.concurrent.TimeoutException("gateway timed out");
