class ExponentialBackoff {
    static <T> T execute(int maxAttempts, long baseMs, long capMs,
                          Callable<T> action) throws Exception {
        int attempt = 0;
        while (true) {
            try {
                return action.call();
            } catch (TransientException e) {
                if (++attempt >= maxAttempts) throw e;
                long delay = Math.min(baseMs * (1L << attempt), capMs);
                log.warn("Attempt {} failed, backing off {}ms", attempt, delay, e);
                Thread.sleep(delay);
            }
        }
    }
}

