import java.util.*;
import java.util.concurrent.*;

// Idempotency key: a stable, unique token for each logical operation
class PaymentRequest {
    String idempotencyKey;
    String accountId;
    double amount;

    PaymentRequest(String idempotencyKey, String accountId, double amount) {
        this.idempotencyKey = idempotencyKey;
        this.accountId = accountId;
        this.amount = amount;
    }
}

class PaymentResult {
    String status;
    PaymentResult(String status) { this.status = status; }
}

// Server side: first call executes, subsequent calls with same key return cached result
class PaymentService {
    Map<String, PaymentResult> processed = new ConcurrentHashMap<>();
    int executionCount = 0;

    PaymentResult charge(PaymentRequest req) {
        return processed.computeIfAbsent(req.idempotencyKey, k -> {
            executionCount++;
            return new PaymentResult("charged " + req.accountId + " $" + req.amount);
        });
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        PaymentService service = new PaymentService();

        // Client: generate key once, reuse on every retry
        String key = UUID.randomUUID().toString();
        PaymentResult result = null;
        for (int i = 0; i < 3; i++) {
            result = service.charge(new PaymentRequest(key, "acc-1", 100.0));
        }

        System.out.println("Result: " + result.status);
        System.out.println("Actual charges executed: " + service.executionCount + " (only once despite 3 calls)");
    }
}

