public:
    unordered_map<string, PaymentResult> processed;
    int executionCount = 0;

    PaymentResult charge(const PaymentRequest& req) {
        auto it = processed.find(req.idempotencyKey);
        if (it == processed.end()) {
            executionCount++;
            PaymentResult result{"charged " + req.accountId + " $" + to_string(req.amount)};
            processed[req.idempotencyKey] = result;
            return result;
        }
        return it->second;
    }
};

