    PaymentService service;

    // Client: generate key once, reuse on every retry (a fixed key simulates a real UUID here)
    string key = "idem-key-123";
    PaymentResult result;
    for (int i = 0; i < 3; i++) {
        result = service.charge({key, "acc-1", 100.0});
    }

    cout << "Result: " << result.status << endl;
    cout << "Actual charges executed: " << service.executionCount << " (only once despite 3 calls)" << endl;
    return 0;
