class RetryWithDLQ {
    private final DeadLetterQueue dlq;

    <T> Optional<T> execute(Callable<T> action, PaymentRequest req) {
        try {
            return Optional.of(BackoffWithJitter.execute(5, 200, 10_000, action));
        } catch (TransientException e) {
            log.error("All retries exhausted for key={}", req.idempotencyKey, e);
            dlq.send(new FailedOperation(req, e, Instant.now()));
            alerting.trigger("payment-retry-exhausted", req.accountId);
            return Optional.empty();
        }
    }
}

// DLQ consumer — runs separately, replays failed operations

class DLQConsumer {
    void processFailed(FailedOperation op) {
        // human review, manual replay, or compensating transaction
        log.info("Replaying failed payment: key={}", op.request.idempotencyKey);
        service.charge(op.request);
    }
}

