};

class RetryWithDLQ {
    DeadLetterQueue& dlq;
public:
    RetryWithDLQ(DeadLetterQueue& dlq) : dlq(dlq) {}

    template <typename Func>
    optional<string> execute(Func action, const PaymentRequest& req, int maxAttempts = 3) {
        int attempt = 0;
        while (attempt < maxAttempts) {
            try {
                return action();
            } catch (const exception& e) {
                attempt++;
                if (attempt >= maxAttempts) {
                    cout << "All retries exhausted for key=" << req.idempotencyKey << endl;
                    dlq.send({req, e.what()});
                    cout << "Alert triggered: payment-retry-exhausted for " << req.accountId << endl;
                    return nullopt;
                }
            }
        }
        return nullopt;
    }
};

// DLQ consumer, runs separately, replays failed operations
class DLQConsumer {
public:
    void processFailed(const FailedOperation& op) {
        // human review, manual replay, or compensating transaction
        cout << "Replaying failed payment: key=" << op.request.idempotencyKey << endl;
    }
};

